package net.civeira.phylax.feature.observe.observedembed.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedembed.domain.ObservedEmbedMaxRangeOptions;

class MaxRangeVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property max range of observed embed ")
  void test_max_range_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> MaxRangeVO.tryFrom("_HOUR_"));
    Assertions.assertEquals(ObservedEmbedMaxRangeOptions.HOUR,
        MaxRangeVO.tryFrom("HOUR").getMaxRange());
    Assertions.assertThrows(ConstraintException.class, () -> MaxRangeVO.tryFrom(null));
    Assertions.assertEquals(ObservedEmbedMaxRangeOptions.HOUR,
        MaxRangeVO.from(ObservedEmbedMaxRangeOptions.HOUR).getMaxRange());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> MaxRangeVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedEmbedMaxRangeOptions.HOUR + "]",
        MaxRangeVO.from(ObservedEmbedMaxRangeOptions.HOUR).toString());
  }
}
